const backup = (p) => { if (fs.existsSync(p) && !fs.existsSync(p + '.bak')) fs.copyFileSync(p, p + '.bak'); };
for (const [rel, content] of Object.entries(FILES)) {
  const p = path.join(root, ...rel.split('/'));
  fs.mkdirSync(path.dirname(p), { recursive: true });
  backup(p);
  fs.writeFileSync(p, content, 'utf8');
  console.log('wrote   ' + rel);
}

// The ashram seal for the login card. This is a small placeholder cut from a screenshot: it is written only if the file does not exist yet.
// Put a sharper seal at public\images\ashram-seal.png (square, transparent or cream background) and it will be used instead.
{
  const p = path.join(root, 'public', 'images', 'ashram-seal.png');
  if (fs.existsSync(p)) console.log('kept    public/images/ashram-seal.png (already there)');
  else { fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, Buffer.from(SEAL_B64, 'base64')); console.log('wrote   public/images/ashram-seal.png (placeholder)'); }
}
// The login page has no site header/footer: wrap them in <ChromeGate> in app/[locale]/layout.tsx (a backup is kept as layout.tsx.bak).
{
  const p = path.join(root, 'src', 'app', '[locale]', 'layout.tsx');
  let s = fs.readFileSync(p, 'utf8');
  const wrap = (src, tag) => {
    const i = src.indexOf('<' + tag + ' ');
    if (i < 0) return null;
    const j = src.indexOf('/>', i);
    if (j < 0) return null;
    return src.slice(0, i) + '<ChromeGate>' + src.slice(i, j + 2) + '</ChromeGate>' + src.slice(j + 2);
  };
  if (s.includes('ChromeGate')) {
    console.log('layout  already uses ChromeGate');
  } else {
    let n = wrap(s, 'Header');
    n = n && wrap(n, 'Footer');
    const k = n ? n.indexOf('import Footer') : -1;
    if (n && k >= 0) {
      n = n.slice(0, k) + "import ChromeGate from '@/components/ChromeGate';" + String.fromCharCode(10) + n.slice(k);
      backup(p);
      fs.writeFileSync(p, n, 'utf8');
      console.log('patched src/app/[locale]/layout.tsx');
    } else {
      console.log(String.fromCharCode(10) + 'Could not patch layout.tsx automatically. Do this by hand:');
      console.log("  1. add:  import ChromeGate from '@/components/ChromeGate';");
      console.log('  2. wrap <Header .../> and <Footer .../> like this:  <ChromeGate><Header .../></ChromeGate>');
    }
  }
}
for (const lang of ['en', 'ta']) {
  const p = path.join(root, 'src', 'dictionaries', lang + '.json');
  backup(p);
  const d = JSON.parse(fs.readFileSync(p, 'utf8'));
  d.auth = DICT[lang].auth;
  fs.writeFileSync(p, JSON.stringify(d, null, 2) + '\n', 'utf8');
  console.log('merged  src/dictionaries/' + lang + '.json');
}
console.log('\nDone. Now: stop the dev server, delete the .next folder, run npm run dev, then open /en/login');
